 catalog_differences as(select e.expected->>'name' as expected_name,a.name as actual_name,e.expected,to_jsonb(a) as actual
 from expected_catalog e full join actual_catalog a on a.name=e.expected->>'name' where e.expected is distinct from to_jsonb(a)),checks(name,passed) as(values
 ('exact_catalog',not exists(select 1 from catalog_differences)),('exact_functions',not exists(select 1 from function_differences)),('vat_incomplete_not_invented',not exists(select 1 from finance_tax_periods where input_vat_status<>'incomplete' or input_vat_amount is not null or net_vat_amount is not null)),
 ('only_confirmed_outgoing_evidence',not exists(select 1 from finance_outgoing_wht_obligations w left join finance_payouts p on p.id=w.payout_source_id where p.status is distinct from 'confirmed')),
 ('foundation_zero_state',not exists(select 1 from public.finance_tax_filings) and not exists(select 1 from public.finance_tax_filing_allocations) and not exists(select 1 from public.finance_tax_filing_audit) and not exists(select 1 from public.finance_tax_remittances) and not exists(select 1 from public.finance_tax_remittance_audit) and not exists(select 1 from finance_cash_transactions where source_tax_remittance_id is not null)),
 ('private_and_rpc_permissions',(coalesce(has_function_privilege('authenticated',to_regprocedure('public.tax_filing_can_manage()'),'EXECUTE'),false)=false
 and not coalesce(has_function_privilege('authenticated',to_regprocedure('public.tax_filing_can_manage()'),'EXECUTE WITH GRANT OPTION'),false)
 and not coalesce(has_function_privilege('anon',to_regprocedure('public.tax_filing_can_manage()'),'EXECUTE'),false)
 and not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl where p.oid=to_regprocedure('public.tax_filing_can_manage()') and acl.grantee=0 and acl.privilege_type='EXECUTE')) and
(coalesce(has_function_privilege('authenticated',to_regprocedure('public.tax_filing_can_remit()'),'EXECUTE'),false)=false
 and not coalesce(has_function_privilege('authenticated',to_regprocedure('public.tax_filing_can_remit()'),'EXECUTE WITH GRANT OPTION'),false)
 and not coalesce(has_function_privilege('anon',to_regprocedure('public.tax_filing_can_remit()'),'EXECUTE'),false)
 and not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl where p.oid=to_regprocedure('public.tax_filing_can_remit()') and acl.grantee=0 and acl.privilege_type='EXECUTE')) and
(coalesce(has_function_privilege('authenticated',to_regprocedure('public.tax_filing_pool(date,text)'),'EXECUTE'),false)=false
